from __future__ import annotations

import json
import logging
import os
import sys
from pathlib import Path

import numpy as np


TASK_ROOT = Path(__file__).resolve().parent
SOURCE_ROOT = TASK_ROOT / "source"
REPORT_PATH = TASK_ROOT / "outputs" / "public_reproduction_report.json"
ANGLES_8 = [0.0, 45.0, -45.0, 90.0, 90.0, -45.0, 45.0, 0.0]


def ensure_source_path() -> None:
    source_path = str(SOURCE_ROOT / "src")
    if source_path not in sys.path:
        sys.path.insert(0, source_path)


def load_public_api():
    ensure_source_path()
    from wrinklefe.analysis import AnalysisConfig, WrinkleAnalysis, WrinkleSpec

    return AnalysisConfig, WrinkleAnalysis, WrinkleSpec


def build_common_kwargs() -> dict[str, object]:
    return {
        "amplitude": 0.15,
        "wavelength": 16.0,
        "width": 8.0,
        "loading": "compression",
        "angles": list(ANGLES_8),
        "nx": 16,
        "ny": 2,
        "nz_per_ply": 1,
        "domain_length": 48.0,
    }


def write_report(payload: dict[str, object], exit_code: int) -> int:
    REPORT_PATH.parent.mkdir(exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT_PATH.write_text(text, encoding="utf-8")
    print(text, end="")
    return exit_code


def make_configuration():
    AnalysisConfig, WrinkleAnalysis, WrinkleSpec = load_public_api()

    config = AnalysisConfig(
        morphology="graded",
        wrinkles=[
            WrinkleSpec(
                amplitude=0.075,
                wavelength=16.0,
                width=8.0,
                ply_interface=3,
                phase_offset=0.0,
            ),
            WrinkleSpec(
                amplitude=0.075,
                wavelength=16.0,
                width=8.0,
                ply_interface=3,
                phase_offset=0.0,
            ),
        ],
        **build_common_kwargs(),
    )
    return WrinkleAnalysis, config


def summarize_result(result):
    failure_max = [
        float(np.max(np.asarray(values)))
        for _, values in sorted(result.failure_indices.items())
    ]
    return {
        "n_nodes": int(result.mesh.n_nodes),
        "n_elements": int(result.mesh.n_elements),
        "field_results_present": result.field_results is not None,
        "fiber_angle_min_rad": float(np.min(result.mesh.fiber_angles)),
        "fiber_angle_max_rad": float(np.max(result.mesh.fiber_angles)),
        "modulus_retention": float(result.modulus_retention),
        "n_failure_criteria": len(failure_max),
        "failure_index_global_max": max(failure_max, default=float("nan")),
    }


def make_constructor_equivalence_pair():
    AnalysisConfig, WrinkleAnalysis, _ = load_public_api()
    base_kwargs = {
        **build_common_kwargs(),
        "morphology": "stack",
        "interface_1": 3,
        "interface_2": 4,
    }
    left = AnalysisConfig(**base_kwargs)
    right = AnalysisConfig(**{**base_kwargs, "phase": 0.0})
    return WrinkleAnalysis, left, right


def run_analysis(analysis_cls, config):
    return analysis_cls(config).run()


def summarize_constructor_equivalence(left, right):
    if left.mesh is None or right.mesh is None:
        raise RuntimeError("constructor equivalence requires mesh results")
    if left.failure_indices is None or right.failure_indices is None:
        raise RuntimeError("constructor equivalence requires FE failure fields")

    left_failure_keys = set(left.failure_indices)
    right_failure_keys = set(right.failure_indices)
    if left_failure_keys != right_failure_keys:
        raise RuntimeError("constructor equivalence produced different criteria")

    failure_deltas = []
    for criterion in sorted(left_failure_keys):
        delta = np.max(
            np.abs(
                np.asarray(left.failure_indices[criterion])
                - np.asarray(right.failure_indices[criterion])
            )
        )
        failure_deltas.append(float(delta))

    mesh_node_delta = float(np.max(np.abs(left.mesh.nodes - right.mesh.nodes)))
    fiber_angle_delta = float(
        np.max(np.abs(left.mesh.fiber_angles - right.mesh.fiber_angles))
    )
    failure_index_delta = max(failure_deltas, default=0.0)

    return {
        "left_route": "morphology=stack",
        "right_route": "morphology=stack, phase=0.0",
        "matched": bool(
            mesh_node_delta <= 1e-12
            and fiber_angle_delta <= 1e-12
            and abs(left.mesh_max_angle_rad - right.mesh_max_angle_rad) <= 1e-12
            and abs(left.modulus_retention - right.modulus_retention) <= 1e-9
            and failure_index_delta <= 1e-9
        ),
        "mesh_node_max_abs_delta": mesh_node_delta,
        "fiber_angle_max_abs_delta": fiber_angle_delta,
        "mesh_max_angle_abs_delta": float(
            abs(left.mesh_max_angle_rad - right.mesh_max_angle_rad)
        ),
        "modulus_retention_abs_delta": float(
            abs(left.modulus_retention - right.modulus_retention)
        ),
        "failure_index_max_abs_delta": failure_index_delta,
        "failure_criteria_count": len(left_failure_keys),
    }


def run_constructor_equivalence_check():
    analysis_cls, left_cfg, right_cfg = make_constructor_equivalence_pair()
    left = run_analysis(analysis_cls, left_cfg)
    right = run_analysis(analysis_cls, right_cfg)
    return summarize_constructor_equivalence(left, right)


def main() -> int:
    os.environ.setdefault("PYTHONHASHSEED", "0")
    logging.getLogger("wrinklefe").setLevel(logging.ERROR)
    try:
        constructor_equivalence = run_constructor_equivalence_check()
    except Exception:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "observation": {"status": "runner_error"},
            },
            2,
        )

    try:
        analysis_cls, cfg = make_configuration()
        result = run_analysis(analysis_cls, cfg)
        summary = summarize_result(result)
    except NotImplementedError:
        return write_report(
            {
                "schema_version": "1.0",
                "status": "pre_fix_expected_failure",
                "observation": {"status": "not_completed"},
                "constructor_equivalence": constructor_equivalence,
            },
            1,
        )
    except Exception:  # noqa: BLE001
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "observation": {"status": "runner_error"},
            },
            2,
        )

    scalar_values = [
        summary["fiber_angle_min_rad"],
        summary["fiber_angle_max_rad"],
        summary["modulus_retention"],
        summary["failure_index_global_max"],
    ]
    finite = all(np.isfinite(v) for v in scalar_values)
    status = "workflow_completed" if finite else "runner_failure"
    exit_code = 0 if finite else 2

    return write_report(
        {
            "schema_version": "1.0",
            "status": status,
            "observation": summary,
            "constructor_equivalence": constructor_equivalence,
        },
        exit_code,
    )


if __name__ == "__main__":
    raise SystemExit(main())

